# MAGIC Welcome to the Databricks Lab 3! In this notebook we will explore viewing data lineage.
# MAGIC
# MAGIC When a table or view is created using Databricks the source tables are automatically captured. 
# MAGIC It doesn't matter it the data object was created via a Workflow, adhoc SQL or notebook or even a 3rd party tool.
# MAGIC As long as Databricks compute created the object the lineage will be captured.
# MAGIC
# MAGIC For this lab it is fine to run all the cells at once. Only images will be displayed.

